//! Emit the SINGLE `@generated` DDS QoS catalogue — `crates/lib-tms/src/generated_qos.rs`: the 8
//! MIL-STD-3071 Annex D.5 named `QosProfile`s, each profile's `QosPolicies` (plain data, so a
//! bake-off DDS adapter in `lib-dds` translates it into its own library's QoS-builder calls — never
//! a silent library-default downgrade), the per-topic profile map (`qos_profile`), and per-topic DDS
//! instance-key field metadata (`key_fields`, lifted from `@key` member annotations). Output goes
//! through `prettyplease` (rustfmt-clean), mirroring [`crate::emit_types::emit_tms`]'s pipeline.
//!
//! The profile -> policy mapping is the MIL-STD-3071 Annex D.5 table (durability/reliability/
//! history/deadline per profile; ownership EXCLUSIVE strength 1, liveliness AUTOMATIC, destination
//! order BY_RECEPTION_TIMESTAMP are constant across every profile). It is NOT derived from the IDL
//! (the IDL only names which profile a topic uses, via the `QoS Profile:` doc-comment line lifted by
//! [`crate::resolve::scan_qos_map`]) — it is the fixed D.5 table, hand-encoded here once. Only the
//! per-topic `qos_profile`/`key_fields` maps are actually IDL-derived (from `Model::topic_qos` and
//! each topic's owning struct's `@key` fields).

use proc_macro2::{Ident, Literal, Span, TokenStream};
use quote::quote;

use crate::model::{Model, RQosProfile};

/// Emit the `lib-tms` `@generated` QoS file. `no_std`, zero deps — the only crate-internal reference
/// is `crate::TmsTopicId` (the 1-byte topic index [`crate::emit_types::emit_tms`] already emits).
pub fn emit_qos(model: &Model) -> Result<String, String> {
    let boilerplate = emit_boilerplate();
    let qos_profile_fn = emit_qos_profile_fn(model);
    let key_fields_fn = emit_key_fields_fn(model);

    let items = quote! {
        use crate::TmsTopicId;

        #boilerplate
        #qos_profile_fn
        #key_fields_fn
    };

    let file =
        syn::parse2::<syn::File>(items).map_err(|e| format!("emitted QoS catalogue invalid: {e}"))?;
    let formatted = prettyplease::unparse(&file);
    Ok(format!(
        "// @generated by tms-idl-codegen — DO NOT EDIT.\n\
         //! Generated DDS QoS catalogue — the 8 MIL-STD-3071 Annex D.5 named QoS profiles, their\n\
         //! policies as plain data, the per-topic profile map, and per-topic DDS instance-key field\n\
         //! metadata.\n\
         //!\n\
         //! Source: `docs/compliance/tms/mil-std-3071_data_model.idl` (the topic-module\n\
         //! `QoS Profile:` doc-comment lines + `@key` member annotations) + the fixed MIL-STD-3071\n\
         //! Annex D.5 profile/policy table (not IDL-expressible — hand-encoded in `emit_qos.rs`).\n\
         //! Regenerate with `just tms-codegen`; `just tms-codegen-check` fails if this file is stale.\n\
         #![allow(clippy::all)]\n\
         #![allow(rustdoc::all)]\n\
         #![cfg_attr(rustfmt, rustfmt::skip)]\n\n{formatted}"
    ))
}

// ---- static boilerplate (the fixed D.5 table — not derived from the IDL) ----------------------

fn emit_boilerplate() -> TokenStream {
    quote! {
        /// DURABILITY QoS kind (DDS `DURABILITY_QOS_POLICY`).
        #[derive(Debug, Clone, Copy, PartialEq, Eq)]
        pub enum Durability {
            Volatile,
            TransientLocal,
        }

        /// RELIABILITY QoS kind (DDS `RELIABILITY_QOS_POLICY`).
        #[derive(Debug, Clone, Copy, PartialEq, Eq)]
        pub enum Reliability {
            BestEffort,
            Reliable,
        }

        /// LIVELINESS QoS kind (DDS `LIVELINESS_QOS_POLICY`). Every MIL-STD-3071 Annex D.5 profile
        /// uses AUTOMATIC (with an INFINITE lease, DDS's default for that kind) — kept as a real (if
        /// currently single-valued) enum so a future profile revision needing
        /// MANUAL_BY_TOPIC/MANUAL_BY_PARTICIPANT is a data change here, not a shape change.
        #[derive(Debug, Clone, Copy, PartialEq, Eq)]
        pub enum Liveliness {
            Automatic,
        }

        /// DESTINATION_ORDER QoS kind (DDS `DESTINATION_ORDER_QOS_POLICY`). Every MIL-STD-3071 Annex
        /// D.5 profile uses BY_RECEPTION_TIMESTAMP.
        #[derive(Debug, Clone, Copy, PartialEq, Eq)]
        pub enum DestinationOrder {
            ByReceptionTimestamp,
        }

        /// A DEADLINE duration: a finite second count, or DDS's `DURATION_INFINITE`.
        #[derive(Debug, Clone, Copy, PartialEq)]
        pub enum QosDuration {
            Infinite,
            Seconds(f32),
        }

        /// One D.5 profile's full policy set, as plain data. A bake-off DDS adapter (`lib-dds`)
        /// translates this into its own library's QoS-builder calls, returning
        /// `DdsError::UnsupportedQos` rather than silently downgrading — never a library default
        /// standing in unexamined.
        #[derive(Debug, Clone, Copy, PartialEq)]
        pub struct QosPolicies {
            pub durability: Durability,
            pub reliability: Reliability,
            pub history_depth: u32,
            pub deadline: QosDuration,
            pub ownership_strength: i32,
            pub liveliness: Liveliness,
            pub destination_order: DestinationOrder,
        }

        /// The 8 named DDS QoS profiles (MIL-STD-3071 Annex D.5). Every TMS topic's
        /// `QoS Profile:` doc-comment line names exactly one of these (validated at codegen time —
        /// see `resolve::build_topic_qos`).
        #[derive(Debug, Clone, Copy, PartialEq, Eq)]
        pub enum QosProfile {
            PublishLast,
            Rare,
            Slow,
            Medium,
            Continuous,
            Command,
            Response,
            Reply,
        }

        impl QosProfile {
            /// This profile's policy set — the MIL-STD-3071 Annex D.5 table, hand-encoded (not
            /// IDL-derived; the IDL only names WHICH profile a topic uses).
            pub const fn policies(self) -> QosPolicies {
                match self {
                    // Discovery / retained-state topics: late joiners must see the last value.
                    QosProfile::PublishLast => QosPolicies {
                        durability: Durability::TransientLocal,
                        reliability: Reliability::Reliable,
                        history_depth: 1,
                        deadline: QosDuration::Infinite,
                        ownership_strength: 1,
                        liveliness: Liveliness::Automatic,
                        destination_order: DestinationOrder::ByReceptionTimestamp,
                    },
                    // Very-low-cadence telemetry (deadline is a safety margin over the ~1000 s
                    // publish period).
                    QosProfile::Rare => QosPolicies {
                        durability: Durability::Volatile,
                        reliability: Reliability::BestEffort,
                        history_depth: 1,
                        deadline: QosDuration::Seconds(2000.0),
                        ownership_strength: 1,
                        liveliness: Liveliness::Automatic,
                        destination_order: DestinationOrder::ByReceptionTimestamp,
                    },
                    // 10 s-cadence telemetry (ControlHardwareUpdate, PowerHardwareUpdate, ...).
                    QosProfile::Slow => QosPolicies {
                        durability: Durability::Volatile,
                        reliability: Reliability::BestEffort,
                        history_depth: 1,
                        deadline: QosDuration::Seconds(20.0),
                        ownership_strength: 1,
                        liveliness: Liveliness::Automatic,
                        destination_order: DestinationOrder::ByReceptionTimestamp,
                    },
                    // 1 s-cadence telemetry (AcMeasurementUpdate, DcMeasurementUpdate, Heartbeat).
                    QosProfile::Medium => QosPolicies {
                        durability: Durability::Volatile,
                        reliability: Reliability::BestEffort,
                        history_depth: 1,
                        deadline: QosDuration::Seconds(3.0),
                        ownership_strength: 1,
                        liveliness: Liveliness::Automatic,
                        destination_order: DestinationOrder::ByReceptionTimestamp,
                    },
                    // 0.1 s-cadence power-balance summaries (Ac/DcSummaryMeasurementUpdate).
                    QosProfile::Continuous => QosPolicies {
                        durability: Durability::Volatile,
                        reliability: Reliability::BestEffort,
                        history_depth: 1,
                        deadline: QosDuration::Seconds(2.0),
                        ownership_strength: 1,
                        liveliness: Liveliness::Automatic,
                        destination_order: DestinationOrder::ByReceptionTimestamp,
                    },
                    // As-needed request topics — reliable, no periodic deadline.
                    QosProfile::Command => QosPolicies {
                        durability: Durability::Volatile,
                        reliability: Reliability::Reliable,
                        history_depth: 1,
                        deadline: QosDuration::Infinite,
                        ownership_strength: 1,
                        liveliness: Liveliness::Automatic,
                        destination_order: DestinationOrder::ByReceptionTimestamp,
                    },
                    // Event-triggered authorization responses — reliable, no periodic deadline.
                    QosProfile::Response => QosPolicies {
                        durability: Durability::Volatile,
                        reliability: Reliability::Reliable,
                        history_depth: 1,
                        deadline: QosDuration::Infinite,
                        ownership_strength: 1,
                        liveliness: Liveliness::Automatic,
                        destination_order: DestinationOrder::ByReceptionTimestamp,
                    },
                    // The shared `Reply` topic: deep history so a slow subscriber still sees every
                    // outstanding reply.
                    QosProfile::Reply => QosPolicies {
                        durability: Durability::Volatile,
                        reliability: Reliability::Reliable,
                        history_depth: 128,
                        deadline: QosDuration::Infinite,
                        ownership_strength: 1,
                        liveliness: Liveliness::Automatic,
                        destination_order: DestinationOrder::ByReceptionTimestamp,
                    },
                }
            }
        }
    }
}

// ---- IDL-derived (per-topic) ---------------------------------------------------------------------

/// A topic-name string as the `TmsTopicId` variant ident — MUST reproduce
/// `emit_types::topic_variant_ident` exactly (both mint an ident straight from the raw topic
/// string), or `TmsTopicId::#id` here would not name the same variant `emit_types.rs` declared.
fn topic_ident(topic: &str) -> Ident {
    safe_ident(topic)
}

fn profile_ident(p: RQosProfile) -> Ident {
    safe_ident(p.ident())
}

/// A Rust identifier, raw-escaped if it collides with a keyword (mirrors `emit_types::safe_ident`;
/// duplicated here so this emitter stays self-contained rather than reaching into a sibling
/// module's private helper).
fn safe_ident(s: &str) -> Ident {
    match syn::parse_str::<Ident>(s) {
        Ok(id) => id,
        Err(_) => Ident::new_raw(s, Span::call_site()),
    }
}

fn emit_qos_profile_fn(model: &Model) -> TokenStream {
    let arms = model.topic_qos.iter().map(|q| {
        let topic_id = topic_ident(&q.topic);
        let profile_id = profile_ident(q.profile);
        quote! { TmsTopicId::#topic_id => QosProfile::#profile_id }
    });
    quote! {
        /// This topic's MIL-STD-3071 Annex D.5 QoS profile. Exhaustive over every `TmsTopicId`
        /// variant — codegen hard-errors (see `resolve::build_topic_qos`) before a topic without a
        /// validated profile ever reaches this match.
        pub const fn qos_profile(t: TmsTopicId) -> QosProfile {
            match t {
                #(#arms),*
            }
        }
    }
}

fn emit_key_fields_fn(model: &Model) -> TokenStream {
    let arms = model.topic_qos.iter().map(|q| {
        let topic_id = topic_ident(&q.topic);
        let owner = model
            .types
            .iter()
            .find(|t| t.topics.iter().any(|tp| tp == &q.topic));
        let keys: Vec<Literal> = owner
            .map(|t| {
                t.fields
                    .iter()
                    .filter(|f| f.is_key)
                    .map(|f| Literal::string(&f.name))
                    .collect()
            })
            .unwrap_or_default();
        quote! { TmsTopicId::#topic_id => &[#(#keys),*] }
    });
    quote! {
        /// This topic's DDS instance-key field names (the Rust/`serde` field spelling), in IDL
        /// declaration order — lifted from each field's `@key` annotation. Empty for a topic whose
        /// type declares no key field.
        pub const fn key_fields(t: TmsTopicId) -> &'static [&'static str] {
            match t {
                #(#arms),*
            }
        }
    }
}
